window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-65a1cba8dae17fdf"]={"versions": [{"id": "FIG-65a1cba8dae17fdf", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P06Protect</code> (ForwardStatus) innerhalb des AUTOSAR E2E-Protokolls (Profil 6). Die Aktivität beschreibt den Ablauf zur Absicherung von Daten bei der Weiterleitung bzw. Übertragung im Sender-/Forwarding-Pfad der E2E-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Aktionen (Action States / Subaktivitäten):\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li>Entscheidungsknoten / Verzweigungen über Guard-Bedingungen:\n<ul class=\"fig-list\"><li><code>[input ok]</code>\n</li><li><code>[wrong input]</code>\n</li></ul>\n</li><li>Endknoten (Activity Final Nodes) mit Rückgabewerten:\n<ul class=\"fig-list\"><li><code>return E2E_E_INPUTERR_NULL</code>\n</li><li><code>return E2E_E_OK</code>\n</li><li>Rechter Endknoten (Fehlerfall bei invaliden Eingabewerten / WRONG_INPUT)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn beim Initialknoten und Übergang zur Prüfung der Eingangsparameter (<code>Verify inputs of the protect function</code>).\n</li><li>Verzweigung anhand der Validierungsergebnisse:\n<ul class=\"fig-list\"><li>Bei fehlerhaften Parametern (NULL-Pointer-Prüfung) Verzweigung nach links zum Aktivitätsendknoten mit Rückgabe <code>return E2E_E_INPUTERR_NULL</code>.\n</li><li>Bei sonstigen ungültigen Parametern (<code>[wrong input]</code>) Verzweigung nach rechts zum Aktivitätsendknoten mit Fehlerrückgabe.\n</li><li>Bei erfolgreicher Prüfung (<code>[input ok]</code>) sequenzieller Schutzablauf:\n a. Berechnung des Offsets (<code>Compute offset</code>).\n b. Schreiben der Datenlänge (<code>Write Length</code>).\n c. Schreiben des Sequenzzählers (<code>Write Counter</code>).\n d. Berechnung der Prüfsumme (<code>Compute CRC</code>).\n e. Schreiben der Prüfsumme in den Datenpuffer (<code>Write CRC</code>).\n f. Inkrementieren des Sequenzzählers im Zustandsmodell (<code>Increment Counter</code>).\n</li></ul>\n</li><li>Erfolgreicher Abschluss am zentralen Aktivitätsendknoten mit <code>return E2E_E_OK</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Ausführungsreihenfolge für die E2E-Profil-6-Schutzfunktion bei Forwarding. Der Ablauf erzwingt eine strikte Parameterprüfung vor Pufferzugriffen. Das Inkrementieren des Zählers erfolgt erst nach erfolgreichem Schreiben von Länge, Zähler und CRC, unmittelbar vor dem Verlassen der Funktion mit Status <code>E2E_E_OK</code>. Pufferinhalte werden direkt manipuliert, weshalb NULL-Pointer-Prüfungen vorab zwingend fehlschlagen müssen (<code>E2E_E_INPUTERR_NULL</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5530a7407f3e1559", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P06Protect</code> (ForwardStatus) innerhalb des AUTOSAR E2E-Protokolls (Profil 6). Die Aktivität beschreibt den Ablauf zur Absicherung von Daten bei der Weiterleitung bzw. Übertragung im Sender-/Forwarding-Pfad der E2E-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Aktionen (Action States / Subaktivitäten):\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li>Entscheidungsknoten / Verzweigungen über Guard-Bedingungen:\n<ul class=\"fig-list\"><li><code>[input ok]</code>\n</li><li><code>[wrong input]</code>\n</li></ul>\n</li><li>Endknoten (Activity Final Nodes) mit Rückgabewerten:\n<ul class=\"fig-list\"><li><code>return E2E_E_INPUTERR_NULL</code>\n</li><li><code>return E2E_E_OK</code>\n</li><li>Rechter Endknoten (Fehlerfall bei invaliden Eingabewerten / WRONG_INPUT)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn beim Initialknoten und Übergang zur Prüfung der Eingangsparameter (<code>Verify inputs of the protect function</code>).\n</li><li>Verzweigung anhand der Validierungsergebnisse:\n<ul class=\"fig-list\"><li>Bei fehlerhaften Parametern (NULL-Pointer-Prüfung) Verzweigung nach links zum Aktivitätsendknoten mit Rückgabe <code>return E2E_E_INPUTERR_NULL</code>.\n</li><li>Bei sonstigen ungültigen Parametern (<code>[wrong input]</code>) Verzweigung nach rechts zum Aktivitätsendknoten mit Fehlerrückgabe.\n</li><li>Bei erfolgreicher Prüfung (<code>[input ok]</code>) sequenzieller Schutzablauf:\n a. Berechnung des Offsets (<code>Compute offset</code>).\n b. Schreiben der Datenlänge (<code>Write Length</code>).\n c. Schreiben des Sequenzzählers (<code>Write Counter</code>).\n d. Berechnung der Prüfsumme (<code>Compute CRC</code>).\n e. Schreiben der Prüfsumme in den Datenpuffer (<code>Write CRC</code>).\n f. Inkrementieren des Sequenzzählers im Zustandsmodell (<code>Increment Counter</code>).\n</li></ul>\n</li><li>Erfolgreicher Abschluss am zentralen Aktivitätsendknoten mit <code>return E2E_E_OK</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Ausführungsreihenfolge für die E2E-Profil-6-Schutzfunktion bei Forwarding. Der Ablauf erzwingt eine strikte Parameterprüfung vor Pufferzugriffen. Das Inkrementieren des Zählers erfolgt erst nach erfolgreichem Schreiben von Länge, Zähler und CRC, unmittelbar vor dem Verlassen der Funktion mit Status <code>E2E_E_OK</code>. Pufferinhalte werden direkt manipuliert, weshalb NULL-Pointer-Prüfungen vorab zwingend fehlschlagen müssen (<code>E2E_E_INPUTERR_NULL</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b641be9e811edb78", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P06Protect</code> (ForwardStatus) innerhalb des AUTOSAR E2E-Protokolls (Profil 6). Die Aktivität beschreibt den Ablauf zur Absicherung von Daten bei der Weiterleitung bzw. Übertragung im Sender-/Forwarding-Pfad der E2E-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Aktionen (Action States / Subaktivitäten):\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li>Entscheidungsknoten / Verzweigungen über Guard-Bedingungen:\n<ul class=\"fig-list\"><li><code>[input ok]</code>\n</li><li><code>[wrong input]</code>\n</li></ul>\n</li><li>Endknoten (Activity Final Nodes) mit Rückgabewerten:\n<ul class=\"fig-list\"><li><code>return E2E_E_INPUTERR_NULL</code>\n</li><li><code>return E2E_E_OK</code>\n</li><li>Rechter Endknoten (Fehlerfall bei invaliden Eingabewerten / WRONG_INPUT)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn beim Initialknoten und Übergang zur Prüfung der Eingangsparameter (<code>Verify inputs of the protect function</code>).\n</li><li>Verzweigung anhand der Validierungsergebnisse:\n<ul class=\"fig-list\"><li>Bei fehlerhaften Parametern (NULL-Pointer-Prüfung) Verzweigung nach links zum Aktivitätsendknoten mit Rückgabe <code>return E2E_E_INPUTERR_NULL</code>.\n</li><li>Bei sonstigen ungültigen Parametern (<code>[wrong input]</code>) Verzweigung nach rechts zum Aktivitätsendknoten mit Fehlerrückgabe.\n</li><li>Bei erfolgreicher Prüfung (<code>[input ok]</code>) sequenzieller Schutzablauf:\n a. Berechnung des Offsets (<code>Compute offset</code>).\n b. Schreiben der Datenlänge (<code>Write Length</code>).\n c. Schreiben des Sequenzzählers (<code>Write Counter</code>).\n d. Berechnung der Prüfsumme (<code>Compute CRC</code>).\n e. Schreiben der Prüfsumme in den Datenpuffer (<code>Write CRC</code>).\n f. Inkrementieren des Sequenzzählers im Zustandsmodell (<code>Increment Counter</code>).\n</li></ul>\n</li><li>Erfolgreicher Abschluss am zentralen Aktivitätsendknoten mit <code>return E2E_E_OK</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Ausführungsreihenfolge für die E2E-Profil-6-Schutzfunktion bei Forwarding. Der Ablauf erzwingt eine strikte Parameterprüfung vor Pufferzugriffen. Das Inkrementieren des Zählers erfolgt erst nach erfolgreichem Schreiben von Länge, Zähler und CRC, unmittelbar vor dem Verlassen der Funktion mit Status <code>E2E_E_OK</code>. Pufferinhalte werden direkt manipuliert, weshalb NULL-Pointer-Prüfungen vorab zwingend fehlschlagen müssen (<code>E2E_E_INPUTERR_NULL</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-65a1cba8dae17fdf", "to": "FIG-5530a7407f3e1559", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5530a7407f3e1559", "to": "FIG-b641be9e811edb78", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
